def _edge_run(seq):
    """Find a non-background same-color segment of length >=2 touching either end."""
    n = len(seq)
    found = []
    for edge in (0, n - 1):
        color = seq[edge]
        if color == 0:
            continue
        lo = edge
        hi = edge + 1
        while lo > 0 and seq[lo - 1] == color:
            lo -= 1
        while hi < n and seq[hi] == color:
            hi += 1
        if hi - lo >= 2 and (lo, hi, color) not in found:
            found.append((lo, hi, color))
    return found


def _find_pair(grid, horizontal):
    h, w = len(grid), len(grid[0])
    if horizontal:
        first, second = _edge_run(grid[0]), _edge_run(grid[-1])
        fixed_first, fixed_second = 0, h - 1
    else:
        first = _edge_run([grid[r][0] for r in range(h)])
        second = _edge_run([grid[r][w - 1] for r in range(h)])
        fixed_first, fixed_second = w - 1, 0
    for a in first:
        for b in second:
            if a[2] == b[2] and a[1] - a[0] == b[1] - b[0]:
                return (a, b, fixed_first, fixed_second)
    return None


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Background is the most frequent color; rail color is determined from boundary runs.
    counts = [0] * 10
    for row in grid:
        for value in row:
            counts[value] += 1
    bg = max(range(10), key=lambda c: counts[c])

    pair = _find_pair(grid, True)
    horizontal = pair is not None
    if pair is None:
        pair = _find_pair(grid, False)
    if pair is None:
        return out
    a, b, fixed_a, fixed_b = pair
    # Rails are ordered top-to-bottom or right-to-left. a/b store runs along them.
    (a0, a1, rail_color), (b0, b1, _) = a, b
    source_colors = {v for row in grid for v in row if v != bg and v != rail_color}

    if horizontal:
        top_r, bottom_r = fixed_a, fixed_b
        for r in range(top_r + 1, bottom_r):
            for c in range(w):
                color = grid[r][c]
                if color not in source_colors:
                    continue
                if a0 <= c < a1:
                    # Marker lies under the top rail: same-column ray to marker,
                    # plus the corresponding offset from the opposite rail.
                    mapped = b0 + (c - a0)
                    for rr in range(top_r + 1, bottom_r):
                        if out[rr][mapped] == bg:
                            out[rr][mapped] = color
                    for rr in range(top_r + 1, r):
                        if out[rr][c] == bg:
                            out[rr][c] = color
                    out[r][c] = 4
                elif b0 <= c < b1:
                    mapped = a0 + (c - b0)
                    for rr in range(top_r + 1, bottom_r):
                        if out[rr][mapped] == bg:
                            out[rr][mapped] = color
                    for rr in range(r + 1, bottom_r):
                        if out[rr][c] == bg:
                            out[rr][c] = color
                    out[r][c] = 4
    else:
