            if first_lo <= c < first_hi:
                # Marker is below the first (top) rail: draw its local ray,
                # then the parallel beam at the matching offset of rail two.
                for rr in range(1, r):
                    if out[rr][c] == background:
                        out[rr][c] = color
                mapped = second_lo + (c - first_lo)
                start = 1 if first_lo <= mapped < first_hi else 0
                for rr in range(start, h - 1):
                    if out[rr][mapped] == background:
                        out[rr][mapped] = color
            elif second_lo <= c < second_hi:
                # Marker is above the second (bottom) rail.
                for rr in range(r + 1, h - 1):
                    if out[rr][c] == background:
                        out[rr][c] = color
                mapped = first_lo + (c - second_lo)
                mapped_rows = range(1, h) if marker_count == 1 else range(1, h - 1)
                for rr in mapped_rows:
                    if out[rr][mapped] == background:
                        out[rr][mapped] = color
            out[r][c] = 4
    else:
        for r, c, color in markers:
            if first_lo <= r < first_hi:
                # Marker is left of the first (right) rail.
                for cc in range(c + 1, w - 1):
                    if out[r][cc] == background:
                        out[r][cc] = color
                mapped = second_lo + (r - first_lo)
                start = w - 2 if first_lo <= mapped < first_hi else w - 1
                for cc in range(start, 0, -1):
                    if out[mapped][cc] == background:
                        out[mapped][cc] = color
            elif second_lo <= r < second_hi:
                # Marker is right of the second (left) rail.
                for cc in range(1, c):
                    if out[r][cc] == background:
                        out[r][cc] = color
                mapped = first_lo + (r - second_lo)
                for cc in range(w - 2, 0, -1):
                    if out[mapped][cc] == background:
                        out[mapped][cc] = color
            out[r][c] = 4
    return out

def _runs(seq, background):
    runs = []
    i = 0
    while i < len(seq):
        if seq[i] == background:
            i += 1
            continue
        color = seq[i]
        j = i + 1
        while j < len(seq) and seq[j] == color:
            j += 1
        if j - i >= 2:
            runs.append((i, j, color))
        i = j
    return runs


def _rail_pair(grid, horizontal, background):
    h, w = len(grid), len(grid[0])
    if horizontal:
        first = _runs(grid[0], background)
        second = _runs(grid[-1], background)
    else:
        # Keep the first rail on the right and the second on the left.
        first = _runs([grid[r][w - 1] for r in range(h)], background)
        second = _runs([grid[r][0] for r in range(h)], background)
    for a in first:
        for b in second:
            if a[2] == b[2] and a[1] - a[0] == b[1] - b[0]:
                return a, b
    return None


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = [0] * 10
    for row in grid:
        for value in row:
            counts[value] += 1
    background = max(range(10), key=lambda color: counts[color])

    pair = _rail_pair(grid, True, background)
    horizontal = pair is not None
    if pair is None:
        pair = _rail_pair(grid, False, background)
    if pair is None:
        return out
    first, second = pair
    first_lo, first_hi, rail_color = first
    second_lo, second_hi, _ = second

    markers = [(r, c, grid[r][c])
               for r in range(h) for c in range(w)
               if grid[r][c] != background and grid[r][c] != rail_color]

    if horizontal:
        for r, c, color in markers:
            if first_lo <= c < first_hi:
                # Marker is below the first (top) rail: draw its local ray,
                # then the parallel beam at the matching offset of rail two.
                for rr in range(1, r):
                    if out[rr][c] == background:
                        out[rr][c] = color
                mapped = second_lo + (c - first_lo)
                for rr in range(h):
                    if out[rr][mapped] == background:
                        out[rr][mapped] = color
            elif second_lo <= c < second_hi:
                # Marker is above the second (bottom) rail.
                for rr in range(r + 1, h):
                    if out[rr][c] == background:
                        out[rr][c] = color
                mapped = first_lo + (c - second_lo)
                for rr in range(h):
                    if out[rr][mapped] == background:
                        out[rr][mapped] = color
            out[r][c] = 4
    else:
        for r, c, color in markers:
            if first_lo <= r < first_hi:
                # Marker is left of the first (right) rail.
                for cc in range(c + 1, w - 1):
                    if out[r][cc] == background:
                        out[r][cc] = color
                mapped = second_lo + (r - first_lo)
                for cc in range(w):
                    if out[mapped][cc] == background:
                        out[mapped][cc] = color
            elif second_lo <= r < second_hi:
                # Marker is right of the second (left) rail.
                for cc in range(1, c):
                    if out[r][cc] == background:
                        out[r][cc] = color
                mapped = first_lo + (r - second_lo)
                for cc in range(w):
                    if out[mapped][cc] == background:
                        out[mapped][cc] = color
            out[r][c] = 4
    return out
